INSERT INTO `movies` (`id`, `title`, `short_summary`, `release_date`, `categories`, `rating`, `length`, `trailer_link`, `image_path`, `hero_path`) VALUES
(2, 'The Godfather', 'The aging patriarch of an organized crime dynasty transfers control of his clandestine empire to his reluctant son.', '1972-03-24', 'drama', '9.2', '2h 55m', 'https://www.youtube.com/watch?v=sY1S34973zA', 'godfather.jpg', 'godfatherhero.jpeg'),
(3, 'The Dark Knight', 'When the menace known as the Joker wreaks havoc and chaos on the people of Gotham, Batman must accept one of the greatest psychological and physical tests of his ability to fight injustice.', '2008-07-18', 'action, drama, mystery', '9.0', '2h 33m', 'https://www.youtube.com/watch?v=EXeTwQWrcwY&t=1s', 'dark_knight.jpg', 'dark_knighthero.jpg'),
(4, 'Schindler\'s List', 'In German-occupied Poland during World War II, industrialist Oskar Schindler gradually becomes concerned for his Jewish workforce after witnessing their persecution by the Nazis.', '1993-11-30', 'history,war,drama', '9.0', '3h 15m', 'https://www.youtube.com/watch?v=mxphAlJID9U', 'schindlers_list.jpg', 'schnindlerhero.jpg'),
(6, 'Inception', 'A thief who steals corporate secrets through the use of dream-sharing technology is given the inverse task of planting an idea into the mind of a C.E.O.', '2010-07-16', 'sci-fi,action', '8.8', '2h 28m', 'https://www.youtube.com/watch?v=YoHD9XEInc0', 'inception.jpg', 'inceptionhero.jpg'),
(7, 'John Wick 4', 'John Wick is on the run after killing a member of the international assassin\'s guild, and with a $14 million price tag on his head, he is the target of hit men and women everywhere.', '2023-05-27', 'Action, Thriller', '8.5', '2h 49m', 'https://www.youtube.com/watch?v=_zMUvY4YiPc', 'john_wick_4.jpg', 'john_wick_4_hero.jpg'),
(8, 'The Last of Us', 'In a world ravaged by a deadly fungus, a teenage girl and a hardened survivor must journey across a post-pandemic United States in a brutal journey of survival.', '2023-06-02', 'action,adventure,drama', '9.2', 'Unknown', 'https://www.youtube.com/watch?v=3qQWZbYMt-c', 'the_last_of_us.jpg', 'the_last_of_us_hero.jpg'),
(9, 'The Mandalorian', 'The Mandalorian and the Child continue their journey, facing enemies and rallying allies as they make their way through a dangerous galaxy in the tumultuous era after the collapse of the Galactic Empire.', '2023-07-15', 'action,adventure,sci-fi', '8.8', 'Unknown', 'https://www.youtube.com/watch?v=weU52X5D_lE', 'the_mandalorian.jpg', 'the_mandalorian_hero.jpg'),
